Using the pre-calculated `_draft_processors` list completely eliminates the overhead of calling `getattr` on every single processor during every draft token generation step, significantly improving speculative decoding throughput.

```python
    @staticmethod
    def _has_speculative_draft_logits_processors(
        sampling_metadata: SamplingMetadata | None,
    ) -> bool:
        if sampling_metadata is None:
            return False
        return bool(getattr(sampling_metadata.logitsprocs, "_draft_processors", []))

    @staticmethod
    def _apply_speculative_draft_logits_processors(
        logits: torch.Tensor,
        sampling_metadata: SamplingMetadata | None,
        num_draft_tokens: list[int] | None = None,
    ) -> torch.Tensor:
        if sampling_metadata is None:
            return logits
        for processor in getattr(sampling_metadata.logitsprocs, "_draft_processors", []):
            logits = processor.apply_to_speculative_draft_logits(logits, num_draft_tokens)
        return logits
```

